import{_ as a,o as s,c as o,e as i}from"./chunks/framework.DRBGAJkr.js";const n="/assets/sistema_ipo_datos.kxoj_O72.png",h=JSON.parse('{"title":"Tipos de datos","description":"Tipos de datos en PHP","frontmatter":{"title":"Tipos de datos","description":"Tipos de datos en PHP","date":"19/10/26"},"headers":[],"relativePath":"php/tipos/index.md","filePath":"04_php/06_tipos/index.md"}'),t={name:"php/tipos/index.md"};function l(r,e,d,c,p,u){return s(),o("div",null,[...e[0]||(e[0]=[i('<div class="daws-objetivos"><div class="daws-objetivos__header"><i class="fa-solid fa-list-check" aria-hidden="true"></i><span>Objetivos</span></div><div class="daws-objetivos__content"><div class="daws-objetivos__title">Qué veremos aquí</div><div class="daws-objetivos__body"><ul><li>Conocer los principales tipos de datos de PHP.</li><li>Comprender la diferencia entre tipos de valores y tipos utilizados en declaraciones.</li><li>Conocer los diferentes formatos de representación de enteros.</li><li>Utilizar funciones de PHP para identificar y trabajar con valores.</li><li>Comprender las cadenas de texto: comillas simples y dobles.</li><li>Conocer Heredoc y Nowdoc.</li></ul></div></div></div><h1 id="los-tipos-y-valores-en-php" tabindex="-1">Los tipos y valores en PHP <a class="header-anchor" href="#los-tipos-y-valores-en-php" aria-label="Permalink to &quot;Los tipos y valores en PHP&quot;">​</a></h1><p>Los programas trabajan continuamente con <strong>datos</strong>: números, textos, valores lógicos, etc. Cada dato tiene un <strong>valor</strong> y pertenece a un <strong>tipo</strong>, que determina cómo se representa y qué operaciones podemos realizar con él.</p><p>Ya vimos en el apartado de <a href="https://manuel.web.infenlaces.com/04_php/05_declaraciones/" target="_blank" rel="noreferrer">declaraciones</a> que las variables permiten identificar y trabajar con valores almacenados en memoria.</p><p><img src="'+n+`" alt="Sistema IPO: instrucciones que procesan datos" width="500" style="display:block;margin:0 auto;"></p><p>PHP es un lenguaje de <strong>tipado dinámico</strong>, lo que significa que el tipo de una variable se determina durante la ejecución y puede cambiar al asignarle un nuevo valor.</p><p>En este tema conoceremos los principales tipos de datos de PHP, cómo se representan sus valores y algunas particularidades de su comportamiento. También aprenderemos a identificar los tipos y a realizar conversiones entre ellos.</p><h2 id="clasificacion-de-los-tipos-de-datos" tabindex="-1">Clasificación de los tipos de datos <a class="header-anchor" href="#clasificacion-de-los-tipos-de-datos" aria-label="Permalink to &quot;Clasificación de los tipos de datos&quot;">​</a></h2><p>PHP dispone de diferentes tipos de datos que podemos clasificar según su naturaleza:</p><table tabindex="0"><thead><tr><th>Categoría</th><th>Tipos</th><th>Descripción</th></tr></thead><tbody><tr><td><strong>Escalares</strong></td><td><code>bool</code>, <code>int</code>, <code>float</code>, <code>string</code></td><td>Representan valores individuales: booleanos, enteros, decimales y cadenas de texto.</td></tr><tr><td><strong>Compuestos</strong></td><td><code>array</code>, <code>object</code></td><td>Permiten representar colecciones de datos y objetos.</td></tr><tr><td><strong>Especiales</strong></td><td><code>null</code>, <code>resource</code></td><td>Representan la ausencia de valor y referencias a recursos externos.</td></tr></tbody></table><p>Esta clasificación corresponde a los tipos de valores que podemos encontrar durante la ejecución de un programa PHP.</p><div class="tip custom-block"><p class="custom-block-title">El caso particular de null</p><p>Aunque <code>null</code> tiene un único valor posible (<code>null</code>), y podría parecer similar a un tipo escalar, PHP lo clasifica como un <strong>tipo especial</strong>.</p><p>Conviene distinguirlo de <code>false</code>:</p><ul><li><code>false</code> es un valor del tipo <code>bool</code>.</li><li><code>null</code> es el único valor del tipo <code>null</code> y representa la ausencia de valor.</li></ul></div><h2 id="tipos-utilizados-en-las-declaraciones" tabindex="-1">Tipos utilizados en las declaraciones <a class="header-anchor" href="#tipos-utilizados-en-las-declaraciones" aria-label="Permalink to &quot;Tipos utilizados en las declaraciones&quot;">​</a></h2><p>PHP permite indicar los tipos de los parámetros y valores de retorno de funciones y métodos, así como los tipos de las propiedades de las clases.</p><p>Además de los tipos anteriores, admite otros que expresan <strong>restricciones o características de los valores aceptados</strong>, pero que no representan necesariamente un tipo independiente de valor durante la ejecución.</p><table tabindex="0"><thead><tr><th>Tipo</th><th>Significado</th></tr></thead><tbody><tr><td><code>callable</code></td><td>Acepta un valor que puede invocarse como una función.</td></tr><tr><td><code>iterable</code></td><td>Acepta un array o un objeto que implemente <code>Traversable</code>.</td></tr><tr><td><code>mixed</code></td><td>Acepta cualquier tipo de valor, incluido <code>null</code>.</td></tr><tr><td><code>void</code></td><td>Indica que una función o método no devuelve un valor utilizable.</td></tr><tr><td><code>never</code></td><td>Indica que una función o método nunca termina normalmente.</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">Tipos de valores y tipos de declaraciones</p><p>No todos los nombres de tipos utilizados en las declaraciones representan tipos independientes de valores.</p><p>Por ejemplo, <code>iterable</code> puede admitir un <code>array</code> o un objeto iterable, pero <code>get_debug_type()</code> seguirá identificando el tipo real del valor.</p><p>Además, no todos los tipos pueden utilizarse en cualquier declaración:</p><ul><li><code>void</code> y <code>never</code> solo pueden emplearse como tipos de retorno.</li><li><code>callable</code> puede utilizarse en parámetros y retornos, pero no directamente como tipo de una propiedad.</li><li><code>mixed</code> puede utilizarse en parámetros, retornos y propiedades. Correspondería a int|bool|string|array|null|object</li></ul></div><h2 id="las-funciones-tambien-pueden-ser-valores" tabindex="-1">Las funciones también pueden ser valores <a class="header-anchor" href="#las-funciones-tambien-pueden-ser-valores" aria-label="Permalink to &quot;Las funciones también pueden ser valores&quot;">​</a></h2><p>En PHP, una función anónima puede <strong>asignarse a una variable, pasarse como argumento o devolverse desde otra función</strong>.</p><p>Por ejemplo, podemos almacenar una función en una variable utilizando la sintaxis de las funciones flecha:</p><div class="language-php vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">php</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;?</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">php</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$sumar </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> fn</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">() =&gt; </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">5</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> +</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 7</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">echo</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> get_debug_type</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">($sumar); </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// Closure</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">echo</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> $sumar();               </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 12</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">var_dump</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">is_callable</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">($sumar)); </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// bool(true)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br></div></div><p>En este ejemplo:</p><ul><li><code>$sumar</code> no contiene el número <code>12</code>, sino una función que podemos ejecutar.</li><li><code>get_debug_type($sumar)</code> devuelve <code>Closure</code>.</li><li><code>$sumar()</code> ejecuta la función y devuelve <code>12</code>.</li><li><code>is_callable($sumar)</code> comprueba si el valor puede invocarse como una función.</li></ul><h3 id="diferencia-entre-closure-y-callable" tabindex="-1">Diferencia entre Closure y callable <a class="header-anchor" href="#diferencia-entre-closure-y-callable" aria-label="Permalink to &quot;Diferencia entre Closure y callable&quot;">​</a></h3><p>Es importante distinguir estos dos conceptos:</p><table tabindex="0"><thead><tr><th>Concepto</th><th>Descripción</th></tr></thead><tbody><tr><td><code>Closure</code></td><td>Clase integrada en PHP cuyos objetos representan funciones anónimas y funciones flecha.</td></tr><tr><td><code>callable</code></td><td>Tipo utilizado en declaraciones para aceptar cualquier valor que pueda invocarse como una función.</td></tr></tbody></table><p>Por tanto, <strong><code>Closure</code> es una clase y <code>callable</code> expresa una capacidad</strong>.</p><p>Un objeto <code>Closure</code> es un valor de tipo <code>object</code>, pero también cumple la condición de ser <code>callable</code>.</p><div class="tip custom-block"><p class="custom-block-title">Funciones como valores</p><p>Este comportamiento permite tratar las funciones como datos: podemos almacenarlas en variables y transmitirlas a otras funciones.</p><p>Es un concepto muy utilizado en la programación moderna, especialmente en las funciones de orden superior, los callbacks y la programación funcional.</p></div><p>En las siguientes secciones estudiaremos los principales tipos de valores de PHP, comenzando por los <strong>tipos escalares</strong>.</p>`,30)])])}const b=a(t,[["render",l]]);export{h as __pageData,b as default};
